import 'package:flutter/material.dart';\nimport 'package:provider/provider.dart';\nimport 'package:file_picker/file_picker.dart';\n\nvoid main() {\n  runApp(const NESWorldApp());\n}\n\nclass NESWorldApp extends StatelessWidget {\n  const NESWorldApp({Key? key}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context) {\n    return MaterialApp(\n      title: 'NES World',\n      theme: ThemeData(\n        brightness: Brightness.dark,\n        primaryColor: Colors.grey[800],\n        scaffoldBackgroundColor: const Color(0xFF0a0a0a),\n        useMaterial3: true,\n      ),\n      home: ChangeNotifierProvider(\n        create: (_) => EmulatorManager(),\n        child: const HomeScreen(),\n      ),\n    );\n  }\n}\n\nclass HomeScreen extends StatelessWidget {\n  const HomeScreen({Key? key}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context) {\n    return Consumer<EmulatorManager>(\n      builder: (context, manager, child) {\n        if (manager.isGameLoaded) {\n          return GameScreen();\n        }\n        return ROMSelectionScreen();\n      },\n    );\n  }\n}\n\nclass ROMSelectionScreen extends StatelessWidget {\n  const ROMSelectionScreen({Key? key}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      body: Container(\n        decoration: LinearGradient(\n          colors: [\n            const Color(0xFF0f0f0f),\n            const Color(0xFF1a1a1a),\n          ],\n          begin: Alignment.topLeft,\n          end: Alignment.bottomRight,\n        ).createShader(Rect.fromLTWH(0, 0, 400, 800)).createShader as BoxDecoration?,\n        child: Center(\n          child: SingleChildScrollView(\n            child: Padding(\n              padding: const EdgeInsets.all(24.0),\n              child: Column(\n                mainAxisAlignment: MainAxisAlignment.center,\n                children: [\n                  Icon(\n                    Icons.games_rounded,\n                    size: 80,\n                    color: Colors.grey[600],\n                  ),\n                  const SizedBox(height: 24),\n                  Text(\n                    'NES WORLD',\n                    style: Theme.of(context).textTheme.headlineLarge?.copyWith(\n                          fontWeight: FontWeight.bold,\n                          fontFamily: 'Courier',\n                          fontSize: 36,\n                        ),\n                  ),\n                  const SizedBox(height: 8),\n                  Text(\n                    'Nintendo Entertainment System Emulator',\n                    style: Theme.of(context).textTheme.bodyMedium?.copyWith(\n                          color: Colors.grey[500],\n                          fontFamily: 'Courier',\n                        ),\n                  ),\n                  const SizedBox(height: 48),\n                  ElevatedButton.icon(\n                    onPressed: () => _loadROM(context),\n                    icon: const Icon(Icons.folder_open),\n                    label: const Text('LOAD ROM FILE'),\n                    style: ElevatedButton.styleFrom(\n                      padding: const EdgeInsets.symmetric(horizontal: 32, vertical: 16),\n                      backgroundColor: Colors.red[700],\n                      shape: RoundedRectangleBorder(\n                        borderRadius: BorderRadius.circular(8),\n                      ),\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n\n  void _loadROM(BuildContext context) async {\n    FilePickerResult? result = await FilePicker.platform.pickFiles(\n      type: FileType.custom,\n      allowedExtensions: ['nes'],\n    );\n\n    if (result != null) {\n      if (context.mounted) {\n        context.read<EmulatorManager>().loadROM(result.files.single.path!);\n      }\n    }\n  }\n}\n\nclass GameScreen extends StatefulWidget {\n  const GameScreen({Key? key}) : super(key: key);\n\n  @override\n  State<GameScreen> createState() => _GameScreenState();\n}\n\nclass _GameScreenState extends State<GameScreen> {\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      body: Container(\n        color: Colors.black,\n        child: Column(\n          children: [\n            // TV Header\n            Container(\n              color: const Color(0xFF4d4d4d),\n              padding: const EdgeInsets.all(16),\n              child: Row(\n                children: [\n                  Text(\n                    'NES WORLD',\n                    style: TextStyle(\n                      color: Colors.grey[400],\n                      fontFamily: 'Courier',\n                      fontSize: 14,\n                      fontWeight: FontWeight.bold,\n                    ),\n                  ),\n                  const Spacer(),\n                  Row(\n                    children: [\n                      Container(\n                        width: 8,\n                        height: 8,\n                        decoration: const BoxDecoration(\n                          color: Colors.red,\n                          shape: BoxShape.circle,\n                        ),\n                      ),\n                      const SizedBox(width: 4),\n                      Text(\n                        'PLAYING',\n                        style: TextStyle(\n                          color: Colors.red,\n                          fontFamily: 'Courier',\n                          fontSize: 10,\n                          fontWeight: FontWeight.bold,\n                        ),\n                      ),\n                    ],\n                  ),\n                ],\n              ),\n            ),\n            // Game Screen\n            Expanded(\n              child: Container(\n                color: Colors.black,\n                child: Center(\n                  child: Column(\n                    mainAxisAlignment: MainAxisAlignment.center,\n                    children: [\n                      Text(\n                        'LOADING...',\n                        style: TextStyle(\n                          color: Colors.green[700],\n                          fontFamily: 'Courier',\n                          fontSize: 12,\n                        ),\n                      ),\n                      const SizedBox(height: 16),\n                      CircularProgressIndicator(\n                        valueColor: AlwaysStoppedAnimation(\n                          Colors.green[700],\n                        ),\n                      ),\n                    ],\n                  ),\n                ),\n              ),\n            ),\n            // Controller\n            Container(\n              color: const Color(0xFF4d4d4d),\n              padding: const EdgeInsets.all(16),\n              child: NESController(),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\nclass NESController extends StatelessWidget {\n  const NESController({Key? key}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context) {\n    return Container(\n      decoration: BoxDecoration(\n        gradient: LinearGradient(\n          colors: [\n            const Color(0xFFb3b3b3),\n            const Color(0xFF999999),\n          ],\n          begin: Alignment.topLeft,\n          end: Alignment.bottomRight,\n        ),\n        borderRadius: BorderRadius.circular(20),\n        boxShadow: [\n          BoxShadow(\n            color: Colors.black.withOpacity(0.5),\n            blurRadius: 10,\n            offset: const Offset(0, 5),\n          ),\n        ],\n      ),\n      padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 16),\n      child: Row(\n        children: [\n          // D-Pad\n          _buildDPad(context),\n          const SizedBox(width: 24),\n          const Spacer(),\n          // Start/Select\n          _buildStartSelect(context),\n          const Spacer(),\n          // A/B Buttons\n          _buildActionButtons(context),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildDPad(BuildContext context) {\n    return Column(\n      children: [\n        Text(\n          'D-PAD',\n          style: TextStyle(\n            fontSize: 8,\n            fontWeight: FontWeight.bold,\n            color: Colors.grey[600],\n            fontFamily: 'Courier',\n          ),\n        ),\n        const SizedBox(height: 4),\n        SizedBox(\n          width: 90,\n          height: 90,\n          child: GridView.count(\n            crossAxisCount: 3,\n            mainAxisSpacing: 2,\n            crossAxisSpacing: 2,\n            children: [\n              const SizedBox.shrink(),\n              _dpadButton(context, '↑', () {}),\n              const SizedBox.shrink(),\n              _dpadButton(context, '←', () {}),\n              const SizedBox.shrink(),\n              _dpadButton(context, '→', () {}),\n              const SizedBox.shrink(),\n              _dpadButton(context, '↓', () {}),\n              const SizedBox.shrink(),\n            ],\n          ),\n        ),\n      ],\n    );\n  }\n\n  Widget _dpadButton(BuildContext context, String label, VoidCallback onPressed) {\n    return GestureDetector(\n      onTap: onPressed,\n      child: Container(\n        decoration: BoxDecoration(\n          color: const Color(0xFF4d4d4d),\n          borderRadius: BorderRadius.circular(4),\n          boxShadow: [\n            BoxShadow(\n              color: Colors.black.withOpacity(0.3),\n              blurRadius: 4,\n            ),\n          ],\n        ),\n        child: Center(\n          child: Text(\n            label,\n            style: const TextStyle(\n              fontSize: 12,\n              fontWeight: FontWeight.bold,\n              color: Colors.black,\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n\n  Widget _buildStartSelect(BuildContext context) {\n    return Column(\n      children: [\n        Text(\n          'SELECT START',\n          style: TextStyle(\n            fontSize: 7,\n            fontWeight: FontWeight.bold,\n            color: Colors.grey[600],\n            fontFamily: 'Courier',\n            letterSpacing: 1,\n          ),\n        ),\n        const SizedBox(height: 12),\n        Row(\n          spacing: 24,\n          children: [\n            _smallButton('SELECT'),\n            _smallButton('START'),\n          ],\n        ),\n      ],\n    );\n  }\n\n  Widget _smallButton(String label) {\n    return Container(\n      decoration: BoxDecoration(\n        color: const Color(0xFF666666),\n        borderRadius: BorderRadius.circular(3),\n        boxShadow: [\n          BoxShadow(\n            color: Colors.black.withOpacity(0.5),\n            blurRadius: 3,\n          ),\n        ],\n      ),\n      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),\n      child: Text(\n        label,\n        style: const TextStyle(\n          fontSize: 9,\n          fontWeight: FontWeight.bold,\n          color: Colors.white,\n          fontFamily: 'Courier',\n        ),\n      ),\n    );\n  }\n\n  Widget _buildActionButtons(BuildContext context) {\n    return Column(\n      children: [\n        Text(\n          'A B',\n          style: TextStyle(\n            fontSize: 8,\n            fontWeight: FontWeight.bold,\n            color: Colors.grey[600],\n            fontFamily: 'Courier',\n            letterSpacing: 2,\n          ),\n        ),\n        const SizedBox(height: 4),\n        Row(\n          spacing: 8,\n          children: [\n            _actionButton('B', Colors.red[700]!),\n            _actionButton('A', Colors.green[700]!),\n          ],\n        ),\n      ],\n    );\n  }\n\n  Widget _actionButton(String label, Color color) {\n    return Container(\n      width: 56,\n      height: 56,\n      decoration: BoxDecoration(\n        color: color,\n        shape: BoxShape.circle,\n        boxShadow: [\n          BoxShadow(\n            color: Colors.black.withOpacity(0.5),\n            blurRadius: 6,\n          ),\n        ],\n      ),\n      child: Center(\n        child: Text(\n          label,\n          style: const TextStyle(\n            fontSize: 18,\n            fontWeight: FontWeight.bold,\n            color: Colors.white,\n            fontFamily: 'Courier',\n          ),\n        ),\n      ),\n    );\n  }\n}\n\nclass EmulatorManager extends ChangeNotifier {\n  bool isGameLoaded = false;\n  String? currentGame;\n\n  void loadROM(String path) {\n    currentGame = path.split('/').last;\n    isGameLoaded = true;\n    notifyListeners();\n  }\n\n  void unloadGame() {\n    isGameLoaded = false;\n    currentGame = null;\n    notifyListeners();\n  }\n}\n